sys_script_include.script:
// MSSCUSTODY-4526 - Created this script for setting the condition for UI action - Refresh Holdings Data
var HoldingUIActionVisibility = Class.create();
HoldingUIActionVisibility.prototype = {
    initialize: function() {},
	RefreshHoldingData_Tradeform: function(source, positionAttribute) {
		var ghss_prop = gs.getProperty("x_hsb11_mss_c_proc.hsbcmss_el_custody_source_system_ghss");
		var gcs_prop = gs.getProperty('x_hsb11_mss_c_proc.hsbcmss_el_custody_source_system_gcs');
		if ((source == ghss_prop || source == gcs_prop) && gs.getProperty("x_hsb11_mss_pos.hsbcmss_el_custodyPositiononDemand_active") == "true")
		{
            return 'true';

        } else {
            return 'false';
        }
	},

    type: 'HoldingUIActionVisibility'
};
